export const respAipDefinitions={respAipClose:{title:'Separate an RESP balance into contribution refunds, returned benefits, and taxable accumulated income',fields:[
 ['respCloseContributions','Confirmed subscriber contribution refund (CAD)',32000,0,100000,1000],
 ['respCloseBenefits','Confirmed government and provincial benefit repayment (CAD)',6400,0,30000,500],
 ['respCloseAip','Confirmed eligible accumulated income payment (CAD)',26000,0,150000,1000],
 ['respAipRoom','Verified available deduction capacity for this AIP (CAD)',15000,0,100000,1000],
 ['respAipPriorRelief','Prior qualifying AIP deductions against its lifetime limit (CAD)',40000,0,50000,1000],
 ['respAipTaxRate','Illustrative regular incremental tax rate (%)',30,0,60,1]
]}};
const cents=v=>Math.round(v*100),moneyFromCents=v=>v/100,roundMoney=v=>cents(v)/100;
export function respAipAllocation(i,deductionChoice=null){
 const contributionsC=cents(i.respCloseContributions),benefitsC=cents(i.respCloseBenefits),aipC=cents(i.respCloseAip),roomC=cents(i.respAipRoom),priorC=cents(i.respAipPriorRelief);
 const remainingLifetimeC=Math.max(0,5000000-priorC),maximumC=Math.min(aipC,roomC,remainingLifetimeC);
 const deductionC=deductionChoice==null?maximumC:cents(deductionChoice);
 if(deductionC<0||deductionC>maximumC)throw Error('Deduction must fit the eligible amount, available tax-year capacity and remaining AIP lifetime limit.');
 const remainingAipC=aipC-deductionC,regularTaxC=cents(remainingAipC/100*i.respAipTaxRate/100),additionalTaxC=cents(remainingAipC/100*.20);
 const subscriberCashC=contributionsC+aipC-deductionC-regularTaxC-additionalTaxC;
 return {contributions:moneyFromCents(contributionsC),benefits:moneyFromCents(benefitsC),aip:moneyFromCents(aipC),deduction:moneyFromCents(deductionC),maximumDeduction:moneyFromCents(maximumC),remainingLifetime:moneyFromCents(remainingLifetimeC),remainingAip:moneyFromCents(remainingAipC),regularTax:moneyFromCents(regularTaxC),additionalTax:moneyFromCents(additionalTaxC),tax:moneyFromCents(regularTaxC+additionalTaxC),subscriberCash:moneyFromCents(subscriberCashC),retirementAssets:moneyFromCents(deductionC),total:moneyFromCents(subscriberCashC+deductionC+benefitsC+regularTaxC+additionalTaxC)};
}
function closeAllocations(i){return {none:respAipAllocation(i,0),maximum:respAipAllocation(i)};}
export function respAipResult(kind,i){
 if(kind!=='respAipClose')throw Error('Unknown RESP accumulated-income view.');
 const p=closeAllocations(i),maximum=p.maximum.maximumDeduction,step=maximum/20;
 const curve=Array.from({length:21},(_,k)=>{const x=k===20?maximum:roundMoney(step*k),r=respAipAllocation(i,x);return {x,value:r.regularTax,additional:r.additionalTax};});
 const remaining=[0,10000,25000,50000],used=[0,25000,40000,50000];
 return {metrics:[['Maximum modeled qualifying AIP deduction',maximum,'money'],['Subscriber cash after illustrative final tax',p.maximum.subscriberCash,'money'],['Illustrative regular and additional AIP tax',p.maximum.tax,'money']],
 note:'Original hypothetical closeout ledger reviewed against CRA public guidance on 25 October 2026. Assume the RESP contract and promoter permit a valid AIP to one original subscriber who meets all current CRA payment conditions; the subscriber is resident in Canada. The specific beneficiary, age and plan-history eligibility checks have already been confirmed outside this model. Subscriber contributions and government/provincial benefits shown have been confirmed payable/refundable or repayable by the promoter. Only contribution refund, benefit repayment and eligible AIP balances enter the snapshot. The modeled subscriber qualifies for the AIP-related lifetime tax reduction; its remaining CAD 50,000 lifetime limit, actual available tax-year deduction capacity and AIP amount each cap the comparison. The entered regular rate is an illustrative flat incremental assumption, not an actual tax bracket, return, advice or prediction. Additional tax is 20% outside Quebec; Quebec’s 12% rate is excluded. All scenario amounts and individual tax components are rounded to cents. The result compares no qualifying deduction with the maximum amount supported by the inputs; it does not verify eligibility, RRSP room, contribution timing, promoter terms, withholding, final tax or future RRSP withdrawal tax. No cash-payment date, benefit eligibility, inflation, investment return, fees or school/EAP scenario is modeled. The first AIP requires RESP termination by the end of February in the following year. This model neither schedules that deadline nor calculates other termination or provincial rules.',
 charts:[
 {id:'resp-aip-closeout-pieces',type:'bar',unit:'money',title:'Start with three confirmed closeout amounts, not one blended balance',rows:[{label:'Refundable subscriber contributions',value:p.maximum.contributions},{label:'Government benefits to repay',value:p.maximum.benefits},{label:'Eligible accumulated income payment',value:p.maximum.aip}],note:'This invented same-date composition sums to CAD 64,400. Contributions, benefits and earnings have different destinations and tax treatment. The entries are assumed independently confirmed by a promoter; this is not a formula for estimating a grant repayment or AIP from a live account.'},
 {id:'resp-aip-allocation-comparison',type:'stackbar',title:'Send each part of the same balance to its modeled destination',unit:'money',seriesNames:['Subscriber cash after illustrative current tax','RRSP/PRPP/SPP before future withdrawal tax','Benefits returned','Illustrative current AIP tax'],rows:[{label:'No qualifying deduction',values:[p.none.subscriberCash,0,p.none.benefits,p.none.tax]},{label:'Maximum modeled qualifying deduction',values:[p.maximum.subscriberCash,p.maximum.retirementAssets,p.maximum.benefits,p.maximum.tax]}],note:'Each bar reconciles to the same original CAD 64,400 balance. Current tax combines assumed regular incremental tax on AIP after any allowed deduction with the separate additional 20% on the residual AIP. The RRSP/PRPP/SPP slice remains a pre-future-tax retirement asset, not free cash or a permanent tax saving. No portfolio return or retirement withdrawal is projected.'},
 {id:'resp-aip-tax-by-deduction',type:'line',unit:'money',xUnit:'money',xLabel:'Qualifying deduction against this AIP (CAD)',title:'Each permitted deduction reduces two modeled tax bases dollar for dollar',series:[{name:'Illustrative regular tax on residual AIP',rows:curve.map(x=>({x:x.x,value:x.value}))},{name:'Additional tax on residual AIP',dash:true,rows:curve.map(x=>({x:x.x,value:x.additional}))}],note:'The curve assumes each deduction amount is actually eligible within current RRSP/PRPP/SPP deduction capacity and the remaining AIP lifetime limit. It uses the selected flat regular rate and fixed 20% additional tax outside Quebec. The selected range ends at the smallest of AIP, entered deduction capacity and the unused lifetime limit; other values are not implied eligible.'},
 {id:'resp-aip-deduction-capacity-grid',type:'heatmap',unit:'money',title:'Maximum qualifying AIP deduction by room and lifetime limit',rowLabel:'Prior AIP relief used (CAD)',columns:remaining.map(x=>x===0?'$0':'$'+(x/1000)+'k'),rows:used.map(prior=>({label:prior===0?'$0':'$'+(prior/1000)+'k',values:remaining.map(room=>moneyFromCents(Math.min(cents(i.respCloseAip),room*100,Math.max(0,5000000-prior*100))))})),unitLabel:'Tax-year deduction capacity →; prior AIP relief used ↓ (CAD)',note:'Cells show the maximum qualifying amount within each tax-year deduction capacity and the remaining lifetime AIP relief ceiling, holding the entered AIP fixed. Column capacities and prior relief used are CAD, shown as $0, $10k, $25k and $50k. The current example’s AIP is CAD 26,000. Previous qualifying relief reduces only the lifetime ceiling; it is not the same as RRSP deduction capacity. Values do not establish that a payment or deduction qualifies.'}
 ]};
}
